/* Общее для страниц раздела «Заявки»: данные макета, счётчики вкладок, разбор дат, сопоставление строк с заявками.
   Подставляется в начало скрипта каждой страницы раздела при сборке (patch/zayavki.mjs). */
const ZK = (() => {
  const REC = [{"id":"HB-10412","t":"R","cl":"Дмитрий Орлов","co":"","pr":"","mg":"Отдел партнёрки","st":"Потенциальная сделка","why":"","tr":"3 ноября"},{"id":"HB-10431","t":"C","cl":"Дмитрий Орлов","co":"ОАЭ","pr":"","mg":"Камила Рахимова","st":"Потенциальная сделка","why":"","tr":"5 ноября"},{"id":"HB-10432","t":"P","cl":"Дмитрий Орлов","co":"ОАЭ","pr":"Marina Gate","mg":"Камила Рахимова","st":"Потенциальная сделка","why":"","tr":"8 ноября"},{"id":"HB-10444","t":"P","cl":"Дмитрий Орлов","co":"ОАЭ","pr":"Dubai Hills Park","mg":"Камила Рахимова","st":"В работе","why":"","tr":"8 ноября"},{"id":"HB-10433","t":"P","cl":"Дмитрий Орлов","co":"ОАЭ","pr":"Creek Residence","mg":"Камила Рахимова","st":"Отложил покупку","why":"","tr":"6 ноября"},{"id":"HB-10446","t":"P","cl":"Дмитрий Орлов","co":"ОАЭ","pr":"Palm Tower","mg":"Камила Рахимова","st":"Отказ","why":"Клиент выбрал другой проект","tr":"6 ноября"},{"id":"HB-10434","t":"C","cl":"Дмитрий Орлов","co":"Таиланд","pr":"","mg":"Не назначен","st":"Новый","why":"","tr":"9 ноября"},{"id":"HB-10418","t":"R","cl":"Анна Гордеева","co":"","pr":"","mg":"Отдел партнёрки","st":"В работе","why":"","tr":"20 октября"},{"id":"HB-10435","t":"C","cl":"Анна Гордеева","co":"Турция","pr":"","mg":"Мехмет Йылмаз","st":"В работе","why":"","tr":"28 октября"},{"id":"HB-10436","t":"P","cl":"Анна Гордеева","co":"Турция","pr":"Antalya Park","mg":"Мехмет Йылмаз","st":"В работе","why":"","tr":"2 ноября"},{"id":"HB-10443","t":"P","cl":"Анна Гордеева","co":"Турция","pr":"Bodrum Bay","mg":"Мехмет Йылмаз","st":"В работе","why":"","tr":"7 ноября"},{"id":"HB-10427","t":"R","cl":"Нина Фёдорова","co":"","pr":"","mg":"Отдел партнёрки","st":"Новый","why":"","tr":"9 ноября"},{"id":"HB-10391","t":"R","cl":"Андрей Крылов","co":"","pr":"","mg":"Отдел партнёрки","st":"Сделка","why":"","tr":"2 сентября"},{"id":"HB-10437","t":"C","cl":"Андрей Крылов","co":"ОАЭ","pr":"","mg":"Камила Рахимова","st":"Сделка","why":"","tr":"10 сентября"},{"id":"HB-10438","t":"P","cl":"Андрей Крылов","co":"ОАЭ","pr":"Creek Residence","mg":"Камила Рахимова","st":"Сделка","why":"","tr":"20 сентября"},{"id":"HB-10377","t":"R","cl":"Ринат Хасанов","co":"","pr":"","mg":"Отдел партнёрки","st":"Потенциальная сделка","why":"","tr":"11 августа"},{"id":"HB-10439","t":"C","cl":"Ринат Хасанов","co":"Грузия","pr":"","mg":"Нико Беридзе","st":"Потенциальная сделка","why":"","tr":"19 августа"},{"id":"HB-10440","t":"P","cl":"Ринат Хасанов","co":"Грузия","pr":"Batumi View","mg":"Нико Беридзе","st":"Потенциальная сделка","why":"","tr":"2 сентября"},{"id":"HB-10385","t":"R","cl":"Олег Громов","co":"","pr":"","mg":"Отдел партнёрки","st":"Отказ","why":"Дубль: такая заявка уже передана Вами","tr":"30 октября"},{"id":"HB-10369","t":"R","cl":"Леонид Маслов","co":"","pr":"","mg":"Отдел партнёрки","st":"Отказ","why":"Клиент уже есть в базе Housebook","tr":"3 ноября"},{"id":"HB-10362","t":"R","cl":"Татьяна Эльман","co":"","pr":"","mg":"Отдел партнёрки","st":"В работе","why":"","tr":"12 октября"},{"id":"HB-10441","t":"C","cl":"Татьяна Эльман","co":"Кипр (юг)","pr":"","mg":"Нико Беридзе","st":"В работе","why":"","tr":"12 октября"},{"id":"HB-10442","t":"P","cl":"Татьяна Эльман","co":"Кипр (юг)","pr":"Paphos Sea View","mg":"Нико Беридзе","st":"Отказ","why":"Проект не входит в партнёрскую сеть","tr":"12 октября"},{"id":"HB-9344","t":"R","cl":"Дмитрий Орлов","co":"","pr":"","mg":"Отдел партнёрки","st":"Сделка","why":"","tr":"14 апреля 2025"},{"id":"HB-8120","t":"R","cl":"Дмитрий Орлов","co":"","pr":"","mg":"Отдел партнёрки","st":"Отказ","why":"Клиент передумал покупать","tr":"2 февраля 2024"}];
  const S = HB.store;
  const MON = { января: 0, февраля: 1, марта: 2, апреля: 3, мая: 4, июня: 5, июля: 6, августа: 7, сентября: 8, октября: 9, ноября: 10, декабря: 11 };
  const dnum = (s) => { const m = /(\d+)\s+([а-я]+)(?:\s+(\d{4}))?/.exec(String(s || '').replace(/ /g, ' ')); return m && m[2] in MON ? Date.UTC(m[3] ? +m[3] : 2026, MON[m[2]], +m[1]) / 864e5 : NaN; };
  const TODAY_T = '10 ноября';
  const TODAY = dnum(TODAY_T);
  const NB = ' ';
  const TYN = { R: 'Тип 1:' + NB + 'запрос', C: 'Тип 2:' + NB + 'страна', P: 'Тип 3:' + NB + 'проект', H: 'Холодная база' };
  const SRC = { 'Дмитрий Орлов': 'Кабинет', 'Анна Гордеева': 'Моя ссылка', 'Нина Фёдорова': 'Моя ссылка', 'Андрей Крылов': 'API', 'Ринат Хасанов': 'Кабинет', 'Олег Громов': 'Кабинет', 'Леонид Маслов': 'API', 'Татьяна Эльман': 'Моя ссылка' };
  const STAT = ['Новый', 'В работе', 'Потенциальная сделка', 'Сделка', 'Отложил покупку', 'Отказ'];
  const uniq = (a) => a.filter((x, i) => x && a.indexOf(x) === i);
  const newReqs = () => S.get('zk.new') || [];
  const coldNew = () => S.get('zk.coldnew') || [];
  const nov = () => HB.isNovice();
  const clientsN = () => (nov() ? 0 : 8) + uniq(newReqs().map((r) => r.name)).filter((n) => !(nov() ? [] : REC.map((x) => x.cl)).includes(n)).length;
  const cnt = () => ({ z: (nov() ? 0 : REC.length) + newReqs().length, k: clientsN(), h: (nov() ? 0 : 104) + coldNew().length });
  const recOfNew = (r) => ({ id: r.no, t: r.code, cl: r.name, co: r.co, pr: r.pr, mg: 'Не назначен', st: 'Новый', why: '', tr: r.date, sr: 'Кабинет' });
  const inDt = (tr, f) => { const d = dnum(tr); if (isNaN(d)) return false; const a = TODAY - d; return f === 'Сегодня' ? a === 0 : f === 'За 7 дней' ? a >= 0 && a <= 6 : a >= 0 && a <= 29; };
  const match = (r, F) => (F.st === 'all' || r.st === F.st) && (F.ty === 'all' || TYN[r.t] === F.ty)
    && (F.co === 'all' || String(r.co || '').split(', ').includes(F.co)) && (F.pr === 'all' || r.pr === F.pr) && (F.mg === 'all' || r.mg === F.mg)
    && (F.dt === 'all' || inDt(r.tr, F.dt)) && (F.sr === 'all' || (r.sr || SRC[r.cl] || 'Кабинет') === F.sr);
  const qmatch = (text, q) => {
    q = String(q || '').trim().toLowerCase().replace(/ /g, ' ');
    if (!q) return true;
    const t = String(text).toLowerCase().replace(/ /g, ' ');
    if (t.includes(q)) return true;
    const dq = q.replace(/\D/g, '');
    return dq.length >= 3 && t.replace(/\D/g, '').includes(dq);
  };
  const toast = (m) => { if (window.__hbToast) window.__hbToast(m); };
  const byId = (id) => REC.find((r) => r.id === id);
  return { REC, S, NB, TYN, STAT, SRC, TODAY_T, dnum, uniq, newReqs, coldNew, cnt, recOfNew, match, qmatch, toast, byId, nov };
})();

/* Страница «Заявки» - вкладка «Холодная база»: добавить контакт, загрузить файл, решения по сомнительным строкам, «Показать ещё». */
const DUB0 = [{"name":"Олег Тимин","ph":"+7 917 22-31","why":"Номер короче обычного","lang":"Русский","st":""},{"name":"Samira Hadi","ph":"+971 50 111 22 3","why":"Язык не совпадает со страной номера","lang":"Английский","st":"k"},{"name":"Тимур Алиев","ph":"+7 777 000-00-00","why":"Номер похож на тестовый","lang":"Казахский","st":"x"}];
const LANGS = ['Русский', 'Английский', 'Казахский', 'Турецкий', 'Португальский'];
const POOL = [['Елена Миронова', 'Русский', '+7 925 340-71-18'], ['Данияр Сейтказин', 'Казахский', '+7 702 455-30-92'], ['Emily Carter', 'Английский', '+44 7911 120-554'], ['Мехмет Каплан', 'Турецкий', '+90 505 330-41-27'], ['Жуан Перейра', 'Португальский', '+351 913 220-48-05'], ['Виктор Андреев', 'Русский', '+7 903 118-26-74'], ['Алия Нургалиева', 'Казахский', '+7 777 210-55-39'], ['Daniel Brooks', 'Английский', '+1 646 555-01-87'], ['Айше Йилмаз', 'Турецкий', '+90 533 740-19-62'], ['Мариана Коста', 'Португальский', '+351 926 450-17-33'], ['Светлана Орлова', 'Русский', '+7 916 802-45-10'], ['Ержан Алимов', 'Казахский', '+7 701 336-84-21']];
const STS = [['badge--start', 'Новый', 'Text AI Housebook'], ['badge--ok', 'Квалификация', 'Voice AI Housebook'], ['badge--ok', 'Выбор страны', 'Voice AI Housebook'], ['badge--muted', 'Отказ', 'Text AI Housebook']];
const DATES = ['1 ноября', '31 октября', '30 октября', '29 октября', '28 октября', '27 октября', '25 октября', '24 октября', '22 октября', '21 октября', '20 октября', '18 октября'];
const blank = () => ({ name: '', phone: '', lang: 'Русский', cm: '', consent: false });
const NB = ' ';

class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { modal: '', form: blank(), errs: {}, errMsg: '', dec: DUB0.map((r) => r.st), more: 0, fileOk: false };
    this.__off = [];
  }
  componentDidMount() {
    const onKey = (e) => { if (e.key === 'Escape' && this.state.modal) this.setState({ modal: '' }); };
    document.addEventListener('keydown', onKey);
    this.__off = [() => document.removeEventListener('keydown', onKey)];
  }
  componentWillUnmount() { this.__off.forEach((f) => f()); }
  renderVals() {
    const S = this.state, set = (o) => this.setState(o), store = ZK.S, nov = ZK.nov(), fm = S.form;
    const cn = ZK.coldNew(), e = {};
    Object.keys(S.errs).forEach((k) => { e[k] = S.errs[k] ? 'is-err' : ''; });
    const upd = (k) => (ev) => set({ form: Object.assign({}, fm, { [k]: ev.target.value }) });
    const on = { name: upd('name'), phone: upd('phone'), cm: upd('cm'), consent: (ev) => set({ form: Object.assign({}, fm, { consent: ev.target.checked }) }) };
    const baseTotal = nov ? 0 : 104, base6 = nov ? 0 : 6;
    const total = baseTotal + cn.length, shown = base6 + cn.length + S.more;
    const mk = (n) => { const p = POOL[n % POOL.length], st = STS[n % STS.length]; return { date: DATES[n % DATES.length], name: p[0].replace(/ /g, NB), lang: p[1], ph: p[2].replace(/ /g, NB), bc: st[0], st: st[1], who: st[2].replace(/ /g, NB), cm: '-' }; };
    const toRow = (x) => ({ date: x.date.replace(/ /g, NB), name: x.name.replace(/ /g, NB), lang: x.lang, ph: x.ph.replace(/ /g, NB), bc: x.bc, st: x.st, who: x.who.replace(/ /g, NB), cm: x.cm });
    const more = []; for (let i = 0; i < S.more; i++) more.push(mk(i));
    const dub = DUB0.map((r, i) => ({
      name: r.name, ph: r.ph, why: r.why, lang: r.lang, none: !S.dec[i], kept: S.dec[i] === 'k', excld: S.dec[i] === 'x',
      keep: () => { const d = S.dec.slice(); d[i] = 'k'; set({ dec: d }); }, excl: () => { const d = S.dec.slice(); d[i] = 'x'; set({ dec: d }); },
      undo: (ev) => { if (ev && ev.preventDefault) ev.preventDefault(); const d = S.dec.slice(); d[i] = ''; set({ dec: d }); }
    }));
    const submitForma = () => {
      const errs = {}, digits = fm.phone.replace(/\D/g, '');
      if (!fm.name.trim()) errs.name = true;
      if (digits.length < 7) errs.phone = true;
      if (!fm.consent) errs.consent = true;
      const msg = errs.name ? 'Укажите имя контакта' : errs.phone ? 'Укажите телефон с кодом страны: не меньше 7 цифр' : errs.consent ? 'Подтвердите согласие клиента на связь' : '';
      if (msg) { set({ errs, errMsg: msg }); return; }
      store.set('zk.coldnew', [{ date: ZK.TODAY_T, name: fm.name.trim(), lang: fm.lang, ph: fm.phone.trim(), bc: 'badge--start', st: 'Новый', who: 'Text AI Housebook', cm: fm.cm.trim() || '-', ts: Date.now() }].concat(cn));
      const cl = (store.get('facts.clients') || []).concat([{ ts: Date.now(), id: 'zc' + Date.now(), tab: 'cold', cold: true, name: fm.name.trim(), phone: fm.phone.trim(), seek: 'Холодный контакт, язык: ' + fm.lang.toLowerCase(), stage: 'c_new', lang: fm.lang, ty: 'Холодная база', wm: 'Холодный', caller: 'Текстовый ассистент', last: 'сегодня', ago: 'сегодня', since: '10 ноября 2026', cm: fm.cm.trim(), upd: 'Контакт принят. Следующий шаг: **команда Housebook позвонит клиенту**.' }]);
      store.set('facts.clients', cl);
      set({ modal: '', errs: {}, errMsg: '', form: blank() });
      ZK.toast('Контакт передан в холодную базу');
    };
    const submitFayl = () => {
      const add = [0, 1, 2, 3, 4].map((i) => Object.assign(mk(i + 6), { date: ZK.TODAY_T, st: 'Новый', bc: 'badge--start', ts: Date.now() + i }));
      store.set('zk.coldnew', add.concat(cn));
      set({ modal: '' });
      ZK.toast('Файл отправлен в холодную базу: добавлено 5 контактов');
    };
    return {
      isPro: !nov, isNovice: nov, cnt: ZK.cnt(),
      openForma: () => set({ modal: 'forma', form: blank(), errs: {}, errMsg: '' }), openFayl: () => set({ modal: 'fayl' }), closeM: () => set({ modal: '' }),
      mForma: S.modal === 'forma', mFayl: S.modal === 'fayl', e, on, errMsg: S.errMsg, submitForma, submitFayl,
      f: { name: fm.name, phone: fm.phone, cm: fm.cm, consent: fm.consent },
      langL: LANGS.map((t) => ({ t, on: fm.lang === t, pick: () => set({ form: Object.assign({}, fm, { lang: t }) }) })),
      dub, keepAll: () => set({ dec: DUB0.map(() => 'k') }), exclAll: () => set({ dec: DUB0.map(() => 'x') }),
      coldNew: cn.map(toRow), coldMore: more, shown, total, hasMore: shown < total,
      more: () => set({ more: Math.min(S.more + 6, Math.max(0, total - base6 - cn.length)) }),
      noContacts: total === 0, hasContacts: total > 0
    };
  }
}
